import { Alert } from '@ho-dev/primitives';

export function AlertMinimal() {
  return (
    <Alert
      variant="info"
      title="Scheduled maintenance"
      description="Deployments pause on Saturday from 02:00 to 04:00 UTC."
    />
  );
}

import { Alert } from '@ho-dev/primitives';

export function AlertRealistic() {
  return (
    <div className="space-y-4">
      <Alert
        variant="error"
        title="Payment failed"
        description="The card ending in 4242 was declined by the issuer. Retry with another payment method."
        link={{ label: 'Update payment method', href: '#payment-methods' }}
      />
      <Alert
        variant="success"
        title="Import finished"
        description="1,284 rows were imported and 6 were skipped because the email was missing."
      />
    </div>
  );
}

import { Badge } from '@ho-dev/primitives';

export function BadgeMinimal() {
  return <Badge>Draft</Badge>;
}

import { Badge } from '@ho-dev/primitives';

const statuses = [
  { label: 'Paid', variant: 'success' as const, fill: 'solid' as const },
  { label: 'Pending', variant: 'warning' as const, fill: 'light' as const },
  { label: 'Refunded', variant: 'info' as const, fill: 'light' as const },
  { label: 'Failed', variant: 'error' as const, fill: 'solid' as const },
];

export function BadgeRealistic() {
  return (
    <div className="flex flex-wrap items-center gap-2">
      {statuses.map((status) => (
        <Badge key={status.label} variant={status.variant} fill={status.fill}>
          {status.label}
        </Badge>
      ))}
    </div>
  );
}

