'use client';

import { Dropdown, DropdownClose, DropdownContent, DropdownTrigger } from '@ho-dev/primitives';

import { useState } from 'react';

export function DropdownMinimal() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <Dropdown isOpen={isOpen} setIsOpen={setIsOpen}>
      <DropdownTrigger
        chevron
        className="border-stroke dark:border-dark-3 rounded-lg border px-4 py-2 text-sm font-medium"
      >
        Actions
      </DropdownTrigger>
      <DropdownContent align="start">
        <DropdownClose>
          <span className="block rounded px-3 py-2 text-sm hover:bg-gray-50 dark:hover:bg-white/5">
            Edit order
          </span>
        </DropdownClose>
      </DropdownContent>
    </Dropdown>
  );
}

'use client';

import { Dropdown, DropdownClose, DropdownContent, DropdownTrigger } from '@ho-dev/primitives';

import { useState } from 'react';

const actions = [
  { label: 'Open order', hint: 'View the full timeline' },
  { label: 'Duplicate', hint: 'Start from this order' },
  { label: 'Archive', hint: 'Hide it from the open list' },
];

export function DropdownRealistic() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <div className="flex justify-end">
      <Dropdown isOpen={isOpen} setIsOpen={setIsOpen}>
        <DropdownTrigger
          chevron
          className="border-stroke dark:border-dark-3 rounded-lg border px-4 py-2 text-sm font-medium"
        >
          Order actions
        </DropdownTrigger>
        <DropdownContent align="end">
          {actions.map((action) => (
            <DropdownClose key={action.label}>
              <span className="block rounded px-3 py-2 hover:bg-gray-50 dark:hover:bg-white/5">
                <span className="text-dark block text-sm font-medium dark:text-white">
                  {action.label}
                </span>
                <span className="text-dark-4 dark:text-dark-6 block text-xs">{action.hint}</span>
              </span>
            </DropdownClose>
          ))}
        </DropdownContent>
      </Dropdown>
    </div>
  );
}

import { InputGroup } from '@ho-dev/primitives';

export function InputGroupMinimal() {
  return <InputGroup label="Email address" type="email" placeholder="you@example.com" />;
}

import { InputGroup } from '@ho-dev/primitives';

export function InputGroupRealistic() {
  return (
    <div className="grid gap-4 sm:grid-cols-2">
      <InputGroup
        label="Search orders"
        placeholder="Order number or email"
        icon={<span aria-hidden="true">⌕</span>}
        iconPosition="left"
      />
      <InputGroup
        label="Work email"
        type="email"
        placeholder="you@example.com"
        required
        error="Enter an email address on the company domain."
      />
    </div>
  );
}
